  var p=new MapSqlParameterSource("id",id).addValue("quote",quoteId).addValue("intent",intentId).addValue("order",own.id()).addValue("seller",intent.sellerOrderId()).addValue("key",key).addValue("hash",commandHash).addValue("quoteHash",fingerprint).addValue("net",Long.parseLong(quote.net())).addValue("increment",Long.parseLong(quote.increment())).addValue("refund",Long.parseLong(quote.refund())).addValue("due",Long.parseLong(quote.additionalDue())).addValue("receipt",mapper.writeValueAsString(accepted)).addValue("at",Timestamp.from(at));
  jdbc.update("INSERT INTO marketplace.claim_fee_assessment(id,quote_id,intent_id,order_id,seller_order_id,request_key,fingerprint,quote_fingerprint,net,increment,refund,additional_due,state,receipt,accepted_at) VALUES(:id,:quote,:intent,:order,:seller,:key,:hash,:quoteHash,:net,:increment,:refund,:due,'RESERVED',CAST(:receipt AS jsonb),:at)",p);
