   jdbc.update("INSERT INTO marketplace.claim_fee_assessment_bucket(assessment_id,bucket_id,order_id,seller_order_id,original_shipment_id,baseline,selected_maximum,target,increment,deducted,additional_due) VALUES(:assessment,:bucket,:order,:seller,:shipment,:baseline,:maximum,:target,:increment,:deducted,:due)",b);
