   var q=new MapSqlParameterSource("id",b.get("bucket_id")).addValue("assessment",command.assessmentId()).addValue("baseline",b.get("baseline")).addValue("target",b.get("target")).addValue("increment",b.get("increment")).addValue("deducted",b.get("deducted")).addValue("due",b.get("additional_due"));if(jdbc.update("UPDATE marketplace.claim_fee_bucket SET assessed_total=:target,reserved_increment=0,active_assessment_id=NULL,deducted_applied=deducted_applied+:deducted,additional_outstanding=additional_outstanding+:due,revision=revision+1 WHERE id=:id AND active_assessment_id=:assessment AND assessed_total=:baseline AND reserved_increment=:increment",q)!=1) { throw new OrderRejected(409); }
